message.content:
I hoisted the repeated base-type lookup and replaced the common matching-size byte-shift loop with a single `memcpy`, keeping the original loop as a fallback for mismatched sizes. This removes per-byte shifting and repeated `GetType()` calls on the hot path.

```include
#include <cstring>
```

```cpp
template <typename T>
T FieldBase::GetValue(const FIT_UINT8 fieldArrayIndex) const
{
    const FIT_UINT8 type = GetType() & FIT_BASE_TYPE_NUM_MASK;
    const FIT_UINT8 size = baseTypeSizes[type];
    if (fieldArrayIndex >= (FIT_UINT8)values.size())
    {
        return *reinterpret_cast<const T*>(baseTypeInvalids[type]);
    }

    const FIT_UINT8* p = values.data() + (fieldArrayIndex * size);

    if (size == sizeof(T))
    {
        T rv;
        std::memcpy(&rv, p, sizeof(T));
        return rv;
    }

    T rv = 0;
    for (int i = 0; i < size; i++)
    {
        rv |= static_cast<T>(p[i]) << (i * 8);
    }
    return rv;
}
```

